output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited inside single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "An agent must not push a cart into a one-cell-wide aisle flanked by shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking a cart at the mouth of a narrow shelf aisle, the agent is obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrievedAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkedAtMouth",
      "discharge": "cartRetrievedAtMouth"
    }
  },
  {
    "id": "cart_required_for_broad_shelf_service",
    "text": "Items on broad, cart-accessible shelf faces should only be handled while the agent has a cart.",
    "abstraction": {
      "state_properties": {
        "broadShelfServiceSpot": {
          "and": [
            "adjShelf",
            {
              "gt": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "broadShelfServiceSpot",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cartless_movement_only_in_on_foot_zones",
    "text": "Except when going to the cart pickup area or walking a narrow shelf-aisle excursion, agents should not move around the store without a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartPickupApproach": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "permittedOnFootZone": {
          "or": [
            "singleFileShelfAisle",
            "narrowAisleMouth",
            "cartPickupApproach"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "permittedOnFootZone"
          }
        ]
      }
    }
  },
  {
    "id": "entering_narrow_aisle_requires_service",
    "text": "If an agent enters a single-file shelf aisle on foot, they are obliged to perform an interaction in that aisle before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": {
        "and": [
          "singleFileShelfAisle",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_narrow_service",
    "text": "After interacting with goods in a single-file shelf aisle, the agent must return to the aisle mouth and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "narrowAisleService": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "cartRetrievedAtMouth": {
          "pre": {
            "and": [
              "narrowAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "narrowAisleService",
      "discharge": "cartRetrievedAtMouth"
    }
  },
  {
    "id": "park_carts_only_at_narrow_mouths",
    "text": "Carts may be parked by interaction only at designated mouths of single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAwayFromMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "narrowAisleMouth"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartParkedAwayFromMouth"
    }
  }
]
